local function check_download_speed(_biz_name, biz_data, downloading_size)
    local speed = -1
    local cur_time_ms = E.system_clock()
    if (not biz_data.last_downloading_size or biz_data.last_downloading_size == 0)
            or (not biz_data.last_downloading_size_time or biz_data.last_downloading_size_time == 0) then
        --biz_data.last_downloading_size_time = os.time()
        biz_data.last_downloading_size_time = cur_time_ms
        biz_data.last_downloading_size = downloading_size
        return 0
    end

    local download_size_diff = downloading_size - biz_data.last_downloading_size
    --E.LOG.debug(TAG, "check_download_speed, downloading_size:" .. tostring(downloading_size) .. ", last_downloading_size:" .. tostring(biz_data.last_downloading_size) .. ", diff:" .. tostring(download_size_diff))
    if download_size_diff > 0 then
        --local diff_time = os.time() - biz_data.last_downloading_size_time
        local diff_time_ms = cur_time_ms - biz_data.last_downloading_size_time
        if diff_time_ms > 1000 then
            biz_data.last_downloading_size_time = cur_time_ms
            biz_data.last_downloading_size = downloading_size

            local download_size_diff_kb = download_size_diff / 1024
            speed = download_size_diff_kb / diff_time_ms * 1000
            speed = math.floor(speed)
            --E.LOG.debug(TAG, "check_download_speed:" .. tostring(speed) .. " KB/s, diff_time:" .. diff_time_ms .. ", diff_kb:" .. tostring(download_size_diff_kb) .. ", bn:" .. tostring(biz_name))
        end
    end

    return speed
end

function M.check_download_speed(biz_name, downloading_size, total_size)
    if not biz_name or biz_name == "" then
        E.LOG.warn(TAG, "check_download_speed skip, param is invalid")
        return 0
    end

    local biz_data = speed_cache[biz_name] or {}
    speed_cache[biz_name] = biz_data

    if type(downloading_size) ~= 'number' then
        downloading_size = downloading_size or 0
        downloading_size = tonumber(downloading_size)
    end

    if type(total_size) ~= 'number' then
        total_size = total_size or 0
        total_size = tonumber(total_size)
    end

    local speed = 0
    --避免中途退出再进入时多打印一次
    if downloading_size > 0 then
        speed = check_download_speed(biz_name, biz_data, downloading_size)
    end

    if total_size > 0 and downloading_size == total_size then
        E.LOG.debug(TAG, "check_download_speed end, clear speed cache, biz_name:" .. tostring(biz_name))
        speed_cache[biz_name] = nil
    end

    return speed
end

function M.reset_download_speed(biz_name)
    --E.LOG.debug(TAG, "reset_download_speed received:" .. tostring(biz_name))
    speed_cache[biz_name] = nil
end

return M